$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$dir=$PSScriptRoot;$items=Get-Content (Join-Path $dir 'images.json') -Raw|ConvertFrom-Json
$counter=@{'#B5B2AC'='#BA9273';'#D4D0CD'='#8AC290';'#839EA6'='#9E7565';'#566178'='#4D8A7E';'#EBF0EE'='#D1AE8A';'#938F85'='#9E7565'}
$chair=@{'#B5B2AC'='#BA9273';'#D4D0CD'='#D1AE8A';'#99BAB5'='#8AC290';'#839EA6'='#68A88E';'#6C8091'='#9E7565'}
$reports=@()
foreach($l in ($items|Where-Object {$_.si -eq 7 -and $_.key -eq '7_1_0'})){$src=[System.Drawing.Bitmap]::FromFile((Join-Path $dir $l.file));if($src.Width -ne 32 -or $src.Height -ne 40){throw '现代侧面尺寸变更'};$map=if($l.name -like '*收银椅'){$chair}elseif($l.name -like '*收银柜台'){$counter}else{@{}};$dst=New-Object System.Drawing.Bitmap 32,40
 for($y=0;$y -lt 40;$y++){for($x=0;$x -lt 32;$x++){$c=$src.GetPixel($x,$y);$h='#{0:X2}{1:X2}{2:X2}' -f $c.R,$c.G,$c.B;$v=$c;if($c.A -gt 0 -and $map.ContainsKey($h)){$t=[System.Drawing.ColorTranslator]::FromHtml($map[$h]);$v=[System.Drawing.Color]::FromArgb($c.A,$t.R,$t.G,$t.B)};$dst.SetPixel($x,$y,$v);if($v.A -ne $c.A){throw '轮廓变化'}}}
 $name=$l.name.Replace('现代 · ','');$file='green-'+$l.index+'.png';if($map.Count -eq 0){Copy-Item -LiteralPath (Join-Path $dir $l.file) -Destination (Join-Path $dir $file)}else{$dst.Save((Join-Path $dir $file))};$reports+=@{name=$name;file=$file;visible=$l.visible};$src.Dispose();$dst.Dispose()
}
if($reports.Count -ne 3){throw '图层不完整'}
function Bbox($b,[int]$xlimit=1000,[int]$xstart=0){$xs=@();$ys=@();for($y=0;$y -lt $b.Height;$y++){for($x=$xstart;$x -lt [Math]::Min($b.Width,$xlimit);$x++){if($b.GetPixel($x,$y).A -gt 0){$xs+=$x;$ys+=$y}}};return @{width=($xs|Measure-Object -Maximum).Maximum-($xs|Measure-Object -Minimum).Minimum+1;height=($ys|Measure-Object -Maximum).Maximum-($ys|Measure-Object -Minimum).Minimum+1}}
$fc=$items|Where-Object {$_.si -eq 1 -and $_.name -eq '收银柜台'};$fr=$items|Where-Object {$_.si -eq 1 -and $_.name -eq '收银机与付款终端'};$b=[System.Drawing.Bitmap]::FromFile((Join-Path $dir $fc.file));$table=(Bbox $b).width;$b.Dispose();$b=[System.Drawing.Bitmap]::FromFile((Join-Path $dir $fr.file));$pc=(Bbox $b 20).width;$b.Dispose();$r=$reports|Where-Object name -eq '收银机与付款终端';$b=[System.Drawing.Bitmap]::FromFile((Join-Path $dir $r.file));$sidepc=(Bbox $b 32 20).height;$b.Dispose();if($table -ne 28 -or $pc -ne 14 -or $sidepc -ne $pc){throw ('绿色正面与侧面尺寸不匹配: 台面='+$table+' 电脑正面='+$pc+' 电脑侧面='+$sidepc)}
$strip=New-Object System.Drawing.Bitmap 64,40;$g=[System.Drawing.Graphics]::FromImage($strip);$g.Clear([System.Drawing.Color]::Transparent);foreach($l in ($items|Where-Object {$_.si -eq 1 -and $_.key -eq '1_0_0' -and $_.visible})){$img=[System.Drawing.Image]::FromFile((Join-Path $dir $l.file));$g.DrawImageUnscaled($img,0,0);$img.Dispose()};foreach($l in $reports){if($l.visible){$img=[System.Drawing.Image]::FromFile((Join-Path $dir $l.file));$g.DrawImageUnscaled($img,32,0);$img.Dispose()}};$g.Dispose();$strip.Save((Join-Path $dir 'strip.png'));$preview=New-Object System.Drawing.Bitmap 640,400;$g=[System.Drawing.Graphics]::FromImage($preview);$g.Clear([System.Drawing.Color]::FromArgb(235,234,226));$g.InterpolationMode=[System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor;$g.PixelOffsetMode=[System.Drawing.Drawing2D.PixelOffsetMode]::Half;$g.DrawImage($strip,0,0,640,400);$preview.Save((Join-Path $dir 'comparison.png'));$g.Dispose();$preview.Dispose();$strip.Dispose();@{layers=$reports;frontCounterLength=$table;sideCounterTopLength=28;frontComputerWidth=$pc;sideComputerLength=$sidepc;verified='沿用已校正现代侧面的台面几何，台面28，电脑14；只恢复绿色暖木配色，形状和电脑图形不变'}|ConvertTo-Json -Depth 10|Set-Content -Encoding utf8 (Join-Path $dir 'measurements.json')


